inputs = ['hzak', 'iveezx', 'xu', 'yda', 'ij']
outputs = ['hzav', 'iveezagzduzv', 'agzduzvagzdu', 'yg', 'ij']

# Find changed pairs manually
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Analyze first few changes to understand patterns
if len(changed_pairs) > 0:
    print("\nAnalyzing first change:")
    idx, inp, outp = changed_pairs[0]
    print(f"  '{inp}' -> '{outp}'")

    # Find differences
    min_len = min(len(inp), len(outp))
    diff_pos = -1
    for i in range(min_len):
        if inp[i] != outp[i]:
            diff_pos = i
            break

    if diff_pos == -1:
        if len(inp) != len(outp):
            diff_pos = min_len

    if diff_pos != -1:
        print(f"  First difference at position {diff_pos}")
        if len(inp) > len(outp):
            print(f"  Removed character(s) at position {diff_pos}")
        elif len(inp) < len(outp):
            print(f"  Added character(s) at position {diff_pos}")
        else:
            print(f"  Changed character at position {diff_pos}")

