inputs = ['hzak', 'iveezx', 'xu', 'yda', 'ij']
outputs = ['hzav', 'iveezagzduzv', 'agzduzvagzdu', 'yg', 'ij']

# Let's look at all the changes in detail
print("Detailed analysis of changes:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")

    # Find positions where strings differ
    min_len = min(len(inp), len(outp))
    diffs = []
    for j in range(max(len(inp), len(outp))):
        if j >= len(inp) or j >= len(outp) or inp[j] != outp[j]:
            diffs.append(j)

    print(f"  Differences at positions: {diffs}")

    # Check for substring patterns
    if len(inp) < len(outp):
        # Check if outp starts with inp and has extra at end
        if outp.startswith(inp):
            extra = outp[len(inp):]
            print(f"  Extra at end: '{extra}'")
        else:
            # Look for common substring
            for j in range(len(inp), 0, -1):
                if inp.endswith(inp[:j]) and outp.startswith(inp[:j]):
                    prefix_len = len(inp[:j])
                    extra = outp[prefix_len:]
                    print(f"  Overlap pattern: '{inp[:j]}' + '{extra}'")
                    break
    elif len(inp) > len(outp):
        # inp is longer, so some characters were removed
        print("  Characters removed")
    else:
        # Same length, characters changed
        print("  Characters changed")

